public final class TFMGetPagesVisitor implements TFMIDocumentHandlerVisitor
{
    TFMPage             mobPage;
    TFMPages            mobPages;
    MapEnumerator		pagesEnum;
    TFMPages			pages;



}

Method.Source:
void visitDocumentHandler(DictClass _subClass, TFMDocumentHandler _documentHandler)
{
    Map categories = new Map(Types::String,Types::Class);
    TFMGetGroupsVisitor getGroupsVisitor = new TFMGetGroupsVisitor(categories);
    getGroupsVisitor.visitDocumentHandler(_subClass, _documentHandler);
    mobPages = _subClass.callObject( methodStr(TFMDocumentHandler, pages), _documentHandler);
    pagesEnum = mobPages.getPages().getEnumerator();
    while(pagesEnum.moveNext())
    {
        mobPage = pagesEnum.currentValue() as TFMPage;

        // add the menu groups that the page belongs to.
        Set categoriesToAdd = categories.exists(mobPage.parmId()) ? categories.lookup(mobPage.parmId()) : new Set(Types::String);
        SetEnumerator categoriesToAddEnumerator = categoriesToAdd.getEnumerator();
        while(categoriesToAddEnumerator.moveNext())
        {
            mobPage.addPageBelongsToMenuGroups(categoriesToAddEnumerator.current());
        }

        mobPage.setDocumentHandler(_documentHandler);

        pages.addPage(mobPage);
    }
}
